export const meta = { name: 'two-fail', description: 'Two agents fail and are caught, one succeeds', phases: [{ title: 'Try' }] }
phase('Try')
let a = null, b = null
try { a = await agent('Reply with only: hi', { label: 'bad model', phase: 'Try', model: 'claude-nonexistent-0' }) } catch (e) { log('a: ' + String(e).slice(0, 60)) }
try { b = await agent('Reply with only: hi', { label: 'bad schema', phase: 'Try', model: 'haiku', schema: { type: 'object', required: ['x'], additionalProperties: false, properties: {} } }) } catch (e) { log('b: ' + String(e).slice(0, 60)) }
const c = await agent('Reply with only: ok', { label: 'fine', phase: 'Try', model: 'haiku' })
return { a, b, c }
